type Stat = {
  label: string
  value: string | number
}

type Props = {
  stats: [Stat, Stat, Stat, Stat] | [Stat, Stat] | Stat[]
  className?: string
}

export function SummaryCard({ stats, className }: Props) {
  return (
    <div
      className={`bg-card rounded-lg border border-border p-5 shadow-card ${className ?? ''}`}
    >
      <div className={`grid gap-4 ${stats.length <= 2 ? 'grid-cols-2' : 'grid-cols-2'}`}>
        {stats.map((stat, i) => (
          <div key={i} className="flex flex-col gap-0.5">
            <span className="text-4xl font-bold text-foreground leading-none">{stat.value}</span>
            <span className="text-xs text-muted-foreground">{stat.label}</span>
          </div>
        ))}
      </div>
    </div>
  )
}
